package com.internalops.workbench;
import com.internalops.api.ApiResponse;import org.springframework.http.ResponseEntity;import org.springframework.web.bind.annotation.*;import java.util.Map;
@RestController @RequestMapping("/api/finance/orders") public class FinanceController{private final FinanceWorkflowService s;public FinanceController(FinanceWorkflowService s){this.s=s;}@PostMapping("/{id}/receipt")public ApiResponse<Map<String,Object>> receipt(@PathVariable long id,@RequestBody FinanceActionRequest r){return ApiResponse.ok(s.receipt(id,r));}@ExceptionHandler(IllegalArgumentException.class)ResponseEntity<ApiResponse<Object>> bad(IllegalArgumentException e){return ResponseEntity.badRequest().body(new ApiResponse<>(false,null,e.getMessage()));}@ExceptionHandler(IllegalStateException.class)ResponseEntity<ApiResponse<Object>> conflict(IllegalStateException e){return ResponseEntity.status(409).body(new ApiResponse<>(false,null,e.getMessage()));}}
